import zipfile,itertools
p='inputs/scogs_fungi.zip'
with zipfile.ZipFile(p) as z:
    names=[n for n in z.namelist() if n.endswith('.mafft')]
    for n in names[:5]:
        lines=z.read(n).decode(errors='replace').splitlines()
        headers=[x for x in lines if x.startswith('>')]
        seqs=[]; s=''
        for x in lines:
            if x.startswith('>'):
                if s: seqs.append(s); s=''
            else: s+=x.strip()
        if s: seqs.append(s)
        print(n, 'sequences',len(headers),'lengths',sorted(set(map(len,seqs))),'headers',headers[:4])
